<script setup>
import { ref, computed, onMounted, nextTick } from 'vue';
import { X, Eye, EyeOff, User } from 'lucide-vue-next';
import { ROLE_OPTIONS, ROLE_LABEL, SECTOR_OPTIONS, VISTA_OPTIONS, PERMISO_LABELS } from '../constants/organization';
import { getEffectiveVistas, getEffectivePermisos, getEffectiveSectorDefault } from '../services/profileService';
import { vTippy } from '../utils/tooltipDirective';
const props=defineProps({ profile:Object,name:String,email:String,canPreview:Boolean,active:Boolean,activeRole:String,activeSector:String,busy:Boolean });
const emit=defineEmits(['close','simulate','stop']);
const role=ref(props.activeRole || ''),sector=ref(props.activeSector || SECTOR_OPTIONS[0]),dialog=ref(null);
const views=computed(() => role.value ? VISTA_OPTIONS.filter(view => getEffectiveVistas(role.value).includes(view.slug)):[]);
const permissions=computed(() => role.value ? Object.entries(getEffectivePermisos(role.value)).filter(([,allowed]) => allowed).map(([key]) => PERMISO_LABELS[key] || key):[]);
function chooseRole() { sector.value=getEffectiveSectorDefault(role.value); }
onMounted(async () => { await nextTick(); dialog.value?.focus?.(); });
function keyboard(event) {
  if(event.key==='Escape' && !props.busy) { event.stopPropagation(); emit('close'); }
  if(event.key!=='Tab') return;
  const nodes=[...(dialog.value?.querySelectorAll('button:not(:disabled),select:not(:disabled)') || [])].filter(node => node.getClientRects().length);
  const first=nodes[0],last=nodes.at(-1),active=globalThis.document?.activeElement;
  if(!first) { event.preventDefault(); return; }
  if(event.shiftKey && (active===first || !nodes.includes(active))) { event.preventDefault(); last.focus(); }
  else if(!event.shiftKey && (active===last || !nodes.includes(active))) { event.preventDefault(); first.focus(); }
}
</script>
<template>
<Teleport to="body"><div class="account-backdrop" @click.self="!busy && emit('close')"><section ref="dialog" class="account-panel" role="dialog" aria-modal="true" aria-labelledby="account-title" tabindex="-1" @keydown="keyboard"><header><h2 id="account-title">{{ canPreview ? 'Mi perfil y vista previa':'Mi perfil' }}</h2><button class="icon" v-tippy="'Cerrar panel'" aria-label="Cerrar panel" :disabled="busy" @click="emit('close')"><X /></button></header><div class="body"><section class="identity"><User /><div><strong>{{ name || profile?.nombre || 'Usuario' }}</strong><p>{{ email || profile?.email || 'Sin correo' }}</p><p>{{ ROLE_LABEL[profile?.role] || profile?.role || 'Sin rol' }} · {{ (profile?.sectoresAsignados || []).join(', ') || profile?.sectorDefault || 'Sin sector' }}</p></div></section><template v-if="canPreview"><p v-if="active" class="active">Simulación activa: <strong>{{ ROLE_LABEL[activeRole] || activeRole }}</strong> · {{ activeSector }}</p><h3>Probar accesos de un perfil</h3><div class="fields"><label>Rol<select v-model="role" :disabled="busy" @change="chooseRole"><option value="" disabled>Seleccionar rol</option><option v-for="option in ROLE_OPTIONS.filter(item => item.value!=='admin')" :key="option.value" :value="option.value">{{ option.label }}</option></select></label><label>Sector<select v-model="sector" :disabled="busy"><option v-for="option in SECTOR_OPTIONS" :key="option">{{ option }}</option></select></label></div><template v-if="role"><div class="section-title">Vistas habilitadas <span>{{ views.length }}</span></div><div class="views"><span v-for="view in views" :key="view.slug">{{ view.label }}</span><p v-if="!views.length">Este rol no tiene vistas configuradas.</p></div><div class="section-title">Permisos del rol</div><p class="permissions">{{ permissions.join(' · ') || 'Sin permisos adicionales' }}</p></template><p class="hint">Simula menú, vistas y sectores con la configuración del rol. Tu cuenta de Firebase sigue siendo administrador y las acciones habilitadas utilizan datos reales.</p></template></div><footer><button v-if="active" class="button" :disabled="busy" @click="emit('stop')"><EyeOff />Volver a administrador</button><button v-if="canPreview" class="button primary" :disabled="busy || !role" @click="emit('simulate',{ role,sector })"><Eye />{{ busy ? 'Aplicando…':active ? 'Cambiar simulación':'Iniciar simulación' }}</button><button v-else class="button" @click="emit('close')">Cerrar</button></footer></section></div></Teleport>
</template>
<style scoped>
.account-backdrop{position:fixed;inset:0;z-index:120;background:#0f172a66;display:flex;align-items:center;justify-content:center;padding:16px}.account-panel{width:min(650px,100%);max-height:calc(100dvh - 32px);background:white;border-radius:9px;display:flex;flex-direction:column;color:#334155;box-shadow:0 20px 60px #0f172a33;font-size:13px}.account-panel header,.account-panel footer{display:flex;align-items:center;gap:8px;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #e2e8f0}.account-panel h2{font-size:17px;font-weight:700}.icon,.button{display:inline-flex;align-items:center;justify-content:center;gap:6px;border:1px solid #cbd5e1;background:white;border-radius:5px;min-height:34px;padding:0 10px;font-weight:600}.icon{width:30px;padding:0;border:0}.icon svg,.button svg{width:16px;height:16px}.primary{background:#2563eb;border-color:#2563eb;color:white}.body{padding:18px;overflow:auto;min-height:0;display:flex;flex-direction:column;gap:14px}.identity{display:flex;gap:12px;padding-bottom:14px;border-bottom:1px solid #e2e8f0}.identity>svg{width:30px;height:30px;color:#64748b;flex:none}.identity strong{font-size:16px;font-weight:700;color:#0f172a}.identity p{font-size:12px;color:#64748b;margin-top:4px;overflow-wrap:anywhere}.account-panel h3{font-size:14px;font-weight:600}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.fields label{display:flex;flex-direction:column;gap:5px;font-size:11px;font-weight:600;color:#64748b}.fields select{padding:8px;border:1px solid #cbd5e1;border-radius:5px;background:white;min-width:0;font-size:13px;color:#334155}.section-title{font-size:12px;font-weight:600}.section-title span{color:#64748b;margin-left:6px}.views{display:flex;flex-wrap:wrap;gap:6px}.views span{padding:4px 7px;background:#eff6ff;color:#1d4ed8;border-radius:4px;font-size:11px}.permissions{font-size:12px;color:#475569;line-height:1.6}.hint{font-size:11px;color:#64748b;line-height:1.6;background:#f8fafc;padding:10px;border-radius:5px}.active{background:#fff7ed;color:#9a3412;padding:9px;border-radius:5px;font-size:12px}.account-panel footer{border-top:1px solid #e2e8f0;border-bottom:0;justify-content:flex-end;flex-wrap:wrap}button:disabled{opacity:.4;cursor:not-allowed}button:focus-visible,select:focus-visible{outline:2px solid #60a5fa;outline-offset:2px}@media(max-width:600px){.account-backdrop{padding:10px}.account-panel{max-height:calc(100dvh - 20px)}.fields{grid-template-columns:1fr}.account-panel footer .button{flex:1;font-size:12px}.body{padding:12px}}
</style>
